const enVuelo = new Map(); // clave -> promesa de la consulta que ya está andando

async function resumenUnaSolaVez(zona) {
  const clave = `resumen:${zona}`;
  const guardado = await cache.get(clave);
  if (guardado !== null) return JSON.parse(guardado);
  if (!enVuelo.has(clave)) {
    enVuelo.set(clave, (async () => {
      try {
        const dato = await resumenDB(zona);
        await cache.set(clave, JSON.stringify(dato), { EX: 60 });
        return dato;
      } finally {
        enVuelo.delete(clave);
      }
    })());
  }
  return enVuelo.get(clave); // los 199 que llegan después esperan esta misma promesa
}

// Una caché de juguete: un Map con vencimiento y un reloj falso que controlamos a mano.
let reloj = 0; // segundos
const guardado = new Map(); // clave -> { valor, vence }
const cache = {
  get(k) {
    const e = guardado.get(k);
    if (!e) return undefined;
    if (reloj >= e.vence) { guardado.delete(k); return undefined; }
    return e.valor;
  },
  set(k, valor, ttl) { guardado.set(k, { valor, vence: reloj + ttl }); },
  del(k) { guardado.delete(k); },
};

let consultasALaBase = 0;
const baseDeDatos = { Z01: 17446 };
async function consultarBase(zona) {
  consultasALaBase++;
  await new Promise((r) => setTimeout(r, 20)); // la base tarda
  return baseDeDatos[zona];
}

// cache-aside: la aplicación mira la caché; si no está, va a la base y guarda.
async function leerZona(zona) {
  const k = "zona:" + zona;
  const enCache = cache.get(k);
  if (enCache !== undefined) return { valor: enCache, de: "caché" };
  const valor = await consultarBase(zona);
  cache.set(k, valor, 10); // TTL de 10 segundos
  return { valor, de: "base" };
}

