// arreglo: guardar la promesa de la consulta en curso para que los demás la esperen
const enVuelo = new Map();
async function leerZonaUnaVez(zona) {
  const k = "zona:" + zona;
  const enCache = cache.get(k);
  if (enCache !== undefined) return { valor: enCache, de: "caché" };
  if (!enVuelo.has(k)) {
    enVuelo.set(k, consultarBase(zona).then((v) => { cache.set(k, v, 10); enVuelo.delete(k); return { valor: v, de: "base" }; }));
  }
  return enVuelo.get(k);
}
